INSERT INTO `changelog` (translation_id, old_text, new_text, version_tag)
SELECT (SELECT id FROM quran_translations WHERE surah_number = 1 AND verse_number = 1), translation_text, 'ฉันเริ่มต้นการอ่านอัลกุรอานด้วยพระนามของอัลลอฮฺ ขอความอนุเคราะห์จากพระองค์ ขอความศิริมงคลด้วยการกล่าวพระนามของพระองค์ ซึ่งคำกล่าวบิสมิลลาฮฺนี้ได้รวมพระนามของพระองค์ไว้ด้วยกันสามพระนาม ได้แก่ 1-(อัลลอฮฺ) ซึ่งหมายถึง ผู้ที่ถูกเคารพสักการะด้วยสิทธิอันชอบธรรม ซึ่งเป็นพระนามเฉพาะสำหรับพระองค์ และจะไม่ถูกตั้งพระนามนี้อื่นจากพระองค์ 2-(อัรเราะฮฺมาน) หมายถึง ผู้ที่เปี่ยมไปด้วยความเมตตาอันล้นพ้น และพระองค์ก็เป็นผู้ทรงเมตตาด้วยตัวของพระองค์เอง และ 3-(อัรเราะฮีม) หมายถึง ผู้ที่เปี่ยมด้วยความเมตตาอันต่อเนื่อง ทรงเมตตาผู้ที่พระองค์ทรงประสงค์จากสิ่งที่พระองค์ทรงสร้างขึ้นมา หนึ่งในนั้นคือ บรรดาผู้ศรัทธาจากปวงบ่าวทั้งมวลของพระองค์', 'v2026-11-10-mukhtasar-proofread'
FROM verse_translations
WHERE surah_number = 1 AND verse_number = 1 AND source_id IN (SELECT id FROM translation_sources WHERE external_type = 'mokhtasr') AND translation_text = 'ฉันเริ่มต้นการอ่านอัลกุรอานด้วยพระนามของอัลลอฮฺ ขอความอนุเคราะห์จากพระองค์ ขอความศิริมงคลด้วยการกล่าวพระนามของพระองค์ ซึ่งคำกล่าวบิสมิลลาฮฺนี้ได้รวมพระนามของพระองค์ไว้ด้วยกันสามพระนาม ได้แก่ 1-(อัลลอฮฺ) ซึ่งหมายถึง ผู้ที่ถูกเคารพสักการะด้วยสิทธิอันชอบธรรม ซึ่งเป็นพระนามเฉพาะสำหรับพระองค์ และจะไม่ถูกตั้งพระนามนี้อื่นจากพระองค์ 2-(อัรเราะฮฺมาน) หมายถึง ผู้ที่เปี่ยมไปด้วยความเมตตาอันล้นพัน และพระองค์ก็เป็นผู้ทรงเมตตาด้วยตัวของพระองค์เอง และ 3-(อัรเราะฮีม) หมายถึง ผู้ที่เปี่ยมด้วยความเมตตาอันต่อเนื่อง ทรงเมตตาผู้ที่พระองค์ทรงประสงค์จากสิ่งที่พระองค์ทรงสร้างขึ้นมา หนึ่งในนั้นคือ บรรดาผู้ศรัทธาจากปวงบ่าวทั้งมวลของพระองค์';
--> statement-breakpoint
