SELECT (SELECT id FROM quran_translations WHERE surah_number = 18 AND verse_number = 2), translation_text, 'พระองค์ยังทำให้มันเป็นคัมภีร์ที่เที่ยงธรรมโดยไม่มีข้อขัดแย้งและไม่มีการสวนทางกัน (เป็นคัมภีร์ที่ประทานมา) เพื่อเตือนให้เหล่าผู้ปฏิเสธได้เกรงกลัวบทลงโทษอันเจ็บแสบจากอัลลอฮฺที่กำลังรอพวกเขาอยู่ และเพื่อแจ้งข่าวดีแก่บรรดาผู้ศรัทธาที่กระทำความดีทั้งหลายว่า สำหรับพวกเขานั้นคือรางวัลอันดีงามที่ไม่มีสิ่งใดเทียบเท่าได้ (นั่นก็คือสรวงสวรรค์)', 'v2026-11-10-mukhtasar-proofread'
