SELECT (SELECT id FROM quran_translations WHERE surah_number = 18 AND verse_number = 6), translation_text, 'บางทีเจ้า-โอ้รอซูลเอ๋ย- อาจจะทำลายชีวิตของเจ้าเองเพราะเสียใจที่พวกเขาไม่ได้ศรัทธาต่อคัมภีร์อัลกุรอานนี้ เจ้าอย่าได้กระทำเช่นนั้น เพราะมันไม่ใช่หน้าที่ของเจ้าที่จะให้ทางนำแก่พวกเขา แต่หน้าที่ของเจ้าคือการเผยแพร่และบอกกล่าวแก่พวกเขาเท่านั้นเอง', 'v2026-11-10-mukhtasar-proofread'
FROM verse_translations
WHERE surah_number = 18 AND verse_number = 6 AND source_id IN (SELECT id FROM translation_sources WHERE external_type = 'mokhtasr') AND translation_text = 'บางทีเจ้า-โอ้รอซูลเอ๋ย- อาจจะทำลายชีวิตของเจ้าเองเพราะเสียใจที่พวกเขาไม่ได้ศรัทธาต่อคัมภีร์อัลกุรอานนี้ เจ้าอย่าได้กระทำเช่นนั้น เพราะมันไม่ไช่หน้าที่ของเจ้าที่จะให้ทางนำแก่พวกเขา แต่หน้าที่ของเจ้าคือการเผยแพร่และบอกกล่าวแก่พวกเขาเท่านั้นเอง';
