INSERT INTO `changelog` (translation_id, old_text, new_text, version_tag)
SELECT (SELECT id FROM quran_translations WHERE surah_number = 18 AND verse_number = 13), translation_text, 'เราจะให้เจ้าได้รู้ -โอ้รอซูลเอ๋ย- เกี่ยวกับเรื่องราวของพวกเขาอย่างแท้จริงโดยปราศจากสิ่งที่คลุมเครือใดๆทั้งสิ้น แท้จริงพวกเขาเป็นชายหนุ่มกลุ่มหนึ่งที่ศรัทธาต่อพระผู้อภิบาลของพวกเขาพร้อมกับได้ปฏิบัติตามบทบัญญัติของพระองค์ พระองค์จึงทรงเพิ่มพูนทางนำให้กับพวกเขา และทรงให้พวกเขายืนหยัดบนสัจธรรม', 'v2026-11-10-mukhtasar-proofread'
FROM verse_translations
WHERE surah_number = 18 AND verse_number = 13 AND source_id IN (SELECT id FROM translation_sources WHERE external_type = 'mokhtasr') AND translation_text = 'เราจะให้เจ้า -โอ้รอซูลเอ๋ย- ได้รู้เกี่ยวกับเรื่องราวของพวกเขาอย่างแท้จริงโดยปราศจากสิ่งที่คลุมเครือใดๆทั้งสิ้น แท้จริงพวกเขาเป็นชายหนุ่มกลุ่มหนึ่งที่ศรัทธาต่อพระผู้อภิบาลของพวกเขาพร้อมกับได้ปฏิบัติตามบทบัญญัติของพระองค์ พระองค์จึงทรงเพิ่มพูนทางนำให้กับพวกเขา และทรงให้พวกเขายืนหยัดบนสัจธรรม';
