INSERT INTO `changelog` (translation_id, old_text, new_text, version_tag)
SELECT (SELECT id FROM quran_translations WHERE surah_number = 18 AND verse_number = 16), translation_text, 'และเมื่อพวกเจ้าปลีกตัวออกห่างจากพวกเขาและละทิ้งการเคารพสักการะสิ่งที่พวกเขาเคารพบูชาอื่นจากอัลลอฮฺแล้ว และพวกเจ้าไม่เคารพสักการะต่อสิ่งใดๆนอกจากอัลลอฮฺองค์เดียว ดังนั้นพวกเจ้าจงเข้าไปในถ้ำหลบภัยเพื่อปกป้องศาสนาของพวกเจ้า พระผู้อภิบาลของพวกเจ้าจะทรงแผ่ความเมตตาของพระองค์แก่พวกเจ้า เพื่อปกป้องคุ้มครองพวกเจ้าจากศัตรู และจะทรงจัดระเบียบการงานของพวกเจ้าให้มันดำเนินไปอย่างง่ายดายและเกิดประโยชน์แก่พวกเจ้า ซึ่งเป็นการทดแทนในสิ่งที่พวกเจ้าได้สูญเสียมันไปคือ การใช้ชีวิตอยู่ร่วมกับกลุ่มชนของตนในบ้านเกิด', 'v2026-11-10-mukhtasar-proofread'
FROM verse_translations
WHERE surah_number = 18 AND verse_number = 16 AND source_id IN (SELECT id FROM translation_sources WHERE external_type = 'mokhtasr') AND translation_text = 'และเมื่อพวกเจ้าปลีกตัวออกห่างจากพวกเขาและละทิ้งการเคารพสักการะสิ่งที่พวกเขาเคารพบูชาอื่นจากอัลลอฮฺแล้ว และพวกเจ้าไม่เคารพสักการะต่อสิ่งใดๆนอกจากอัลลอฮฺองค์เดียว ดังนั้นพวกเจ้าจงเข้าไปในถ้ำหลบภัยเพื่อปกป้องศาสนาของพวกเจ้า พระผู้อภิบาลของพวกเจ้าจะทรงแผ่ความเมตตาของพระองค์แก่พวกเจ้า เพื่อปกป้องคุ้มครองพวกเจ้าจากศัตรู และจะทรงจัดระเบียบการงานของพวกเจ้าให้มันดำเนินไปอย่างง่ายดายและเกิดประประโยชน์แก่พวกเจ้า ซึ่งเป็นการทดแทนในสิ่งที่พวกเจ้าได้สูญเสียมันไปคือ การใช้ชีวิตอยู่ร่วมกับกลุ่มชนของตนในบ้านเกิด';
