INSERT INTO `changelog` (translation_id, old_text, new_text, version_tag)
SELECT (SELECT id FROM quran_translations WHERE surah_number = 18 AND verse_number = 18), translation_text, 'และถ้าหากเจ้าได้เห็นพวกเขา เจ้าก็จะเห็นเหมือนกับว่าพวกเขาตื่นเพราะตาเปิดอยู่ ทั้ง ๆที่ความจริงแล้วพวกเขากำลังหลับอยู่ และพระองค์ทรงพลิกพวกเขามาทางด้านขวาบ้าง และทางด้านซ้ายบ้างสลับกัน เพื่อไม่ให้แผ่นดินกัดกินเรือนร่างของพวกเขา และสุนัขของพวกเขาก็ยังนั่งยืดสองขาหน้าเฝ้าอยู่ที่ปากถ้ำ หากเจ้าฉะโงกจ้องมองพวกเขา แน่นอนเจ้าจะหันหลังเตลิดหนีตกใจกลัวพวกเขาอย่างแรง', 'v2026-11-10-mukhtasar-proofread'
FROM verse_translations
WHERE surah_number = 18 AND verse_number = 18 AND source_id IN (SELECT id FROM translation_sources WHERE external_type = 'mokhtasr') AND translation_text = 'และถ้าหากเจ้าได้เห็นพวกเขา เจ้าก็จะเห็นเหมือนกับว่าพวกเขาตื่นเพราะตาเปิดอยู่ ทั้ง ๆที่ความจริงแล้วพวกกำลังเขาหลับอยู่ และพระองค์ทรงพลิกพวกเขามาทางด้านขวาบ้าง และทางด้านซ้ายบ้างสลับกัน เพื่อไม่ให้แผ่นดินกัดกินเรือนร่างของพวกเขา และสุนัขของพวกเขาก็ยังนั่งยืดสองขาหน้าเฝ้าอยู่ที่ปากถ้ำ หากเจ้าฉะโงกจ้องมองพวกเขา แน่นอนเจ้าจะหันหลังเตลิดหนีตกใจกลัวพวกเขาอย่างแรง';
