INSERT INTO `changelog` (translation_id, old_text, new_text, version_tag)
SELECT (SELECT id FROM quran_translations WHERE surah_number = 18 AND verse_number = 29), translation_text, 'และจงกล่าวเถิด -โอ้รอซูลเอ๋ย- แก่ผู้ที่เมินเฉยจากการระลึกถึงอัลลอฮฺเนื่องจากหัวใจที่หลงลืมของพวกเขา ว่า "สิ่งที่ฉันได้นำมายังพวกเจ้านั้น เป็นสัจธรรมที่แท้จริง ที่มาจากอัลลอฮฺไม่ใช่มาจากฉัน และฉันจะไม่ตอบรับคำร้องขอของพวกเจ้าที่จะขับไล่ผู้ศรัทธาที่ยากไร้ให้ออกไปจากฉัน ดังนั้น ใครก็ตามที่ประสงค์จะศรัทธาต่อสัจธรรมนี้ ก็ศรัทธาได้และเขาจะมีความสุขยิ่งกับสิ่งที่พระองค์จะตอบแทนของเขา และใครก็ตามที่ประสงค์จะปฏิเสธ ก็ปฏิเสธได้ และเขาจะเศร้าใจที่สุดกับการลงโทษที่รอเขาอยู่ แท้จริงแล้ว พระองค์ทรงเตรียมไว้สำหรับผู้ที่เลือกจะปฏิเสธศรัทธาต่อพระองค์ซึ่งขุมไฟนรกที่ใหญ่หลวง กำแพงของมันได้ล้อมรอบพวกเขาไว้ทั้งหมด พวกเขาไม่สามารถหนีออกไปได้ และถ้าหากพวกเขาจะร้องขอน้ำดื่มเนื่องจากกระหายน้ำมากๆนั้น พวกเขาจะได้รับน้ำที่ร้อนเหมือนกับน้ำมันที่เดือดอยู่ในกะทะร้อน จนทำให้ใบหน้าของพวกเขาไหม้ไปหมด มันช่างเป็นเครื่องดื่มที่ชั่วช้าที่สุด นอกจากมันจะไม่ช่วยดับความกระหายแล้ว มันยังเพิ่มความกระหายด้วยซ้ำ แถมยังไม่ช่วยดับเปลวไฟที่กำลังเผาผลาญผิวหนังของพวกเขา และขุมไฟนรกนั้น ช่างเป็นที่พำนักอันเลยร้ายที่สุดสำหรับพวกเขาอีกด้วย"', 'v2026-11-10-mukhtasar-proofread'
FROM verse_translations
