SELECT (SELECT id FROM quran_translations WHERE surah_number = 18 AND verse_number = 31), translation_text, 'เหล่าบรรดาผู้ศรัทธาและประกอบการดีนั้น สำหรับพวกเขาจะได้รับสรวงสวรรค์เป็นที่พำนักของพวกเขาชั่วนิรันดร์ มีลำน้ำจืดแห่งสรวงสรรค์หลายสายไหลผ่านใต้ที่พำนักของพวกเขา พวกเขาจะได้ประดับกำไลทอง และสวมอาภรณ์สีเขียวทำด้วยผ้าไหมละเอียดและผ้าไหมหยาบ นอนเอกเขนกบนเตียงที่ตกแต่งด้วยผ้าม่านที่สวยงาม ช่างเป็นผลตอบแทนอันประเสริฐยิ่งและเป็นที่พำนักที่แสนดียิ่ง', 'v2026-11-10-mukhtasar-proofread'
FROM verse_translations
WHERE surah_number = 18 AND verse_number = 31 AND source_id IN (SELECT id FROM translation_sources WHERE external_type = 'mokhtasr') AND translation_text = 'เหล่าบรรดาผู้ศรัทธาและประกอบการดีนั้น สำหรับพวกเขาจะได้รับสรวงสวรรค์เป็นที่พำนักของพวกชั่วนิรันดร์ มีลำน้ำจืดแห่งสรวงสรรค์หลายสายไหลผ่านใต้ที่พำนักของพวกเขา พวกเขาจะได้ประดับกำไลทอง และสวมอาภรณ์สีเขียวทำด้วยผ้าไหมละเอียดและผ้าไหมหยาบ นอนเอกเขนกบนเตียงที่ตกแต่งด้วยผ้าม่านที่สวยงาม ช่างเป็นผลตอบแทนอันประเสริฐยิ่งและเป็นที่พำนักที่แสนดียิ่ง';
