INSERT INTO `changelog` (translation_id, old_text, new_text, version_tag)
SELECT (SELECT id FROM quran_translations WHERE surah_number = 18 AND verse_number = 35), translation_text, 'และผู้ปฏิเสธศรัทธาก็ได้เดินเข้าไปในสวนของเขาพร้อมกับเพื่อนบ้านของเขาที่เป็นผู้ศรัทธา เพื่อที่จะอวดสวนของเขาแก่เพื่อนบ้าน ในขณะที่เขาได้อธรรมต่อตนเองด้วยการปฏิเสธศรัทธาและการลำพองตน เขาก็ได้กล่าวแก่เพื่อนบ้านว่า "ฉันไม่คิดว่าสวนแห่งนี้จะถูกทำลายไปอย่างสิ้นเชิง ดังที่เจ้าเห็นอยู่กับตา เพราะว่าฉันได้จัดระบบไว้ให้มันอย่างดี"', 'v2026-11-10-mukhtasar-proofread'
FROM verse_translations
WHERE surah_number = 18 AND verse_number = 35 AND source_id IN (SELECT id FROM translation_sources WHERE external_type = 'mokhtasr') AND translation_text = 'และผู้ปฏิเสธศรัทธาก็ได้เดินเข้าไปในสวนของเขาพร้อมกับเพื่อนบ้านของเขาที่เป็นผู้ศรัทธา เพื่อที่จะอวดสวนของเขาแก่เพื่อนบ้าน ในขณะท่เขาได้อธรรมต่อตนเองด้วยการปฏิเสธศรัทธาและการลำพองตน เขาก็ได้กล่าวแก่เพื่อนบ้านว่า "ฉันไม่คิดว่าสวนแห่งนี้จะถูกทำลายไปอย่างสิ้นเชิง ดังที่เจ้าเห็นอยู่กับตา เพราะว่าฉันได้จัดระบบไว้ให้มันอย่างดี"';
