SELECT (SELECT id FROM quran_translations WHERE surah_number = 18 AND verse_number = 42), translation_text, 'ในที่สุดสิ่งที่เพื่อนบ้านผู้ศรัทธาคาดไว้นั้นก็ได้เกิดขึ้นจริง ทำให้ผลผลิตในสวนของผู้ปฏิเสธศรัทธาถูกทำลายไปหมด แล้วเขาก็ประกบฝ่ามือทั้งสองด้วยความเสียใจและเสียดายที่สุดต่อทรัพย์สินที่หมดไปกับการดูแลรักษาสวนองุ่นแห่งนี้ ในขณะที่ซุ้มไม้เลื้อยเพื่อปลูกองุ่นนั้นพังถล่มลงมาทั้งหมด เขาก็ได้กล่าวว่า "ไม่น่าเป็นเช่นนี้เลย หากฉันได้ศรัทธาต่อพระผู้อภิบาลของฉันเพียงผู้เดียว และไม่ตั้งสิ่งใดเลยเป็นภาคีกับพระองค์ในการเคารพสักการะ"', 'v2026-11-10-mukhtasar-proofread'
