SELECT (SELECT id FROM quran_translations WHERE surah_number = 18 AND verse_number = 45), translation_text, 'และเจ้า -โอ้รอซูลเอ๋ย- จงยกอุทาหรณ์เกี่ยวกับการสลายที่เร็วนักของโลกใบนี้แก่ผู้ที่ลุ่มหลงกับมันว่า "มันเปรียบเสมือนกับพฤกษชาติแห่งโลกที่งอกเงยขึ้นมาอย่างอุดมสมบูรณ์จากน้ำฝนที่พระองค์ทรงโปรยลงมาจากฟากฟ้า แต่หลังจากนั้น มันก็กลับกลายเป็นเศษพืชแห้งกรังที่ถูกลมพัดปลิวว่อนไปทุกหนแห่ง แล้วแผ่นดินก็จะกลับมาเป็นพื้นที่ว่างเปล่าไร้พืชผลเช่นเดิม ซึ่งอัลลอฮฺทรงมีอำนาจเหนือทุกสิ่ง และไม่มีสิ่งใดที่สามารถทำให้พระองค์หมดความสามารถไปได้ พระองค์จึงประสงค์ที่จะให้สิ่งใดมีชีวิตหรือตายไปก็ได้"', 'v2026-11-10-mukhtasar-proofread'
FROM verse_translations
WHERE surah_number = 18 AND verse_number = 45 AND source_id IN (SELECT id FROM translation_sources WHERE external_type = 'mokhtasr') AND translation_text = 'และเจ้า -โอ้รอซูลเอ๋ย- จงยกอุทธาหรณ์เกี่ยวกับการสลายที่เร็วนักของโลกใบนี้แก่ผู้ที่ลุ่มหลงกับมันว่า "มันเปรียบเสมือนกับพฤกษชาติแห่งโลกที่งอกเงยขึ้นมาอย่างอุดมสมบูรณ์จากน้ำฝนที่พระองค์ทรงโปรยลงมาจากฟากฟ้า แต่หลังจากนั้น มันก็กลับกลายเป็นเศษพืชแห้งกรังที่ถูกลมพัดปลิวว่อนไปทุกหนแห่ง แล้วแผ่นดินก็จะกลับมาเป็นพื้นที่ว่างเปล่าไร้พืชผลเช่นเดิม ซึ่งอัลลอฮฺทรงมีอำนาจเหนือทุกสิ่ง และไม่มีสิ่งใดที่สามารถทำให้พระองค์หมดความสามารถไปได้ พระองค์จึงประสงค์ที่จะให้สิ่งใดมีชีวิตหรือตายไปก็ได้"';
