INSERT INTO `changelog` (translation_id, old_text, new_text, version_tag)
SELECT (SELECT id FROM quran_translations WHERE surah_number = 18 AND verse_number = 59), translation_text, 'และหมู่บ้านเหล่านั้นที่ไม่ได้ศรัทธาต่ออัลลอฮฺ และมันอยู่ใกล้ๆ พวกเจ้า เช่นหมู่บ้านของกลุ่มชนชาวนบีฮูด และกลุ่มชนชาวนบีศอและฮฺและกลุ่มชนชาวนบีชูอัยบฺ ซึ่งเราได้ทำลายพวกเขาเมื่อพวกเขาได้อธรรมต่อตนเองด้วยการปฏิเสธศรัทธาและกระทำบาปต่าง ๆ และเราได้กำหนดเวลาที่จะลงโทษพวกเขาไว้แล้ว', 'v2026-11-10-mukhtasar-proofread'
FROM verse_translations
WHERE surah_number = 18 AND verse_number = 59 AND source_id IN (SELECT id FROM translation_sources WHERE external_type = 'mokhtasr') AND translation_text = 'และหมู่บ้านเหล่านั้นที่ไม่ได้ศรัทธาต่ออัลลอฮฺ และมันอยู่ใกล้ๆ พวกเจ้า เช่นหมู่บ้านของกลุ่มชนชาวนบีฮูด และกลุ่มชนชาวนบีศอและฮฺและกลุ่มชนชาวนบีชูอัยบฺ ซึ่งเราได้ทำลายพวกเขาเมื่อพวกเขาได้อธรรมต่อตนเองด้วยการปฏิเสธศรัทธาและกระทำบาปต่า ๆ และเราได้กำหนดเวลาที่จะลงโทษพวกเขาไว้แล้ว';
