SELECT (SELECT id FROM quran_translations WHERE surah_number = 18 AND verse_number = 61), translation_text, 'ดังนั้นทั้งสองก็ได้ออกเดินทาง เมื่อทั้งสองได้ไปถึงสถานที่นัดพบของทะเลทั้งสองพวกเขาก็ลืมเรื่องปลาของพวกเขาที่เตรียมไว้เป็นอาหาร อัลลอฮฺก็ได้ชุบชีวิตปลาตัวนั้นขึ้นมา มันจึงได้มุดหนีไปในทะเล และได้วาดเส้นทางไว้เป็นแนวทางยาวไปตามตัวของมัน(คล้ายอุโมงค์เล็กๆ)ซึ่งน้ำทะเลไม่สามารถจะเข้าไปได้', 'v2026-11-10-mukhtasar-proofread'
FROM verse_translations
WHERE surah_number = 18 AND verse_number = 61 AND source_id IN (SELECT id FROM translation_sources WHERE external_type = 'mokhtasr') AND translation_text = 'ดังนั้นทั้งสองก็ได้ออกเดินทาง เมื่อทั้งสองได้ไปถึงสถานที่นัดพบของทะเลทั้งสองพวกเขาก็ลืมเรื่องปลาของพวกเขาที่เตรียมไว้เป็นอาหาร อัลลอฮฺก็ได้ชุปชีวิตปลาตัวนั้นขึ้นมา มันจึงได้มุดหนีไปในทะเล และได้วาดเส้นทางไว้เป็นแนวทางยาวไปตามตัวของมัน(คล้ายอุโมงค์เล็กๆ)ซึ่งน้ำทะเลไม่สามารถจะเข้าไปได้';
