SELECT (SELECT id FROM quran_translations WHERE surah_number = 18 AND verse_number = 65), translation_text, 'และเมื่อทั้งสองได้ถึง ณ จุดที่ปลาได้หายไป พวกเขาก็ได้พบบ่าวคนหนึ่งของเราที่มีคุณธรรม (นั่นคือ อัลเคาะฎิร อะลัยฮิสสลาม) ซึ่งเป็นบ่าวที่เราได้ประทานความเมตตาแก่เขาและเราได้สอนเขาซึ่งความรู้ที่คนอื่นๆ ไม่สามารถที่จะรับรู้ได้ และความรู้นี้คือสิ่งที่เป็นเนื้อหาหลักในเรื่องนี้', 'v2026-11-10-mukhtasar-proofread'
